import { describe, it, expect } from 'vitest';
import QRCode from 'qrcode';
import { Jimp } from 'jimp';
import { analyzeQrCodes } from '../QrCodeAnalyzer';

/**
 * Real fixtures throughout — actual PNG-encoded QR codes generated by the
 * `qrcode` package (a devDependency, used only to build test images; never
 * imported by production code) and decoded by the real production
 * QrCodeAnalyzer (Jimp + jsQR), not mocks.
 */

async function blankImage(width = 50, height = 50): Promise<Buffer> {
  const img = new Jimp({ width, height, color: 0xffffffff });
  return img.getBuffer('image/png');
}

async function qrPng(text: string, opts: { width?: number; margin?: number } = {}): Promise<Buffer> {
  return QRCode.toBuffer(text, { type: 'png', width: opts.width ?? 200, margin: opts.margin ?? 4 });
}

describe('analyzeQrCodes', () => {
  it('1. an image without any QR code reports not detected', async () => {
    const result = await analyzeQrCodes(await blankImage());
    expect(result.detected).toBe(false);
    expect(result.codes).toEqual([]);
  });

  it('2. decodes a valid benign text QR code', async () => {
    const png = await qrPng('Meeting at 3pm in room 204');
    const result = await analyzeQrCodes(png);
    expect(result.detected).toBe(true);
    expect(result.codes).toEqual([{ payload: 'Meeting at 3pm in room 204', type: 'TEXT' }]);
  });

  it('3. decodes a valid URL QR code and classifies it as type URL', async () => {
    const png = await qrPng('https://amaz0n-login.example.com/secure/verify');
    const result = await analyzeQrCodes(png);
    expect(result.detected).toBe(true);
    expect(result.codes[0]).toEqual({ payload: 'https://amaz0n-login.example.com/secure/verify', type: 'URL' });
  });

  it('4. decodes a shortened-URL QR code (type URL, no special-casing needed — the existing URL pipeline handles shorteners)', async () => {
    const png = await qrPng('https://bit.ly/abc123');
    const result = await analyzeQrCodes(png);
    expect(result.codes[0].type).toBe('URL');
    expect(result.codes[0].payload).toBe('https://bit.ly/abc123');
  });

  it('6. detects multiple QR codes placed side by side in one image', async () => {
    const qr1 = await qrPng('https://amazon.com/account', { width: 150 });
    const qr2 = await qrPng('https://bit.ly/xyz789', { width: 150 });
    const canvas = new Jimp({ width: 400, height: 200, color: 0xffffffff });
    canvas.composite(await Jimp.read(qr1), 20, 20);
    canvas.composite(await Jimp.read(qr2), 220, 20);
    const combined = await canvas.getBuffer('image/png');

    const result = await analyzeQrCodes(combined);
    const payloads = result.codes.map((c) => c.payload).sort();
    expect(payloads).toEqual(['https://amazon.com/account', 'https://bit.ly/xyz789'].sort());
  });

  it('7. a malformed/non-image buffer fails safely instead of throwing', async () => {
    const garbage = Buffer.from('this is not an image at all, just plain garbage bytes 0000000');
    const result = await analyzeQrCodes(garbage);
    expect(result.detected).toBe(false);
    expect(result.codes).toEqual([]);
    expect(result.errors).toBeDefined();
  });

  it('8. an oversized image (dimension bound) is rejected safely rather than decoded', async () => {
    // A real, tiny PNG whose declared dimensions exceed the safety bound —
    // constructed directly rather than actually rendering an 8000px image,
    // to keep the test fast while still exercising the real bound check.
    const img = new Jimp({ width: 8001, height: 2, color: 0xffffffff });
    const png = await img.getBuffer('image/png');
    const result = await analyzeQrCodes(png);
    expect(result.detected).toBe(false);
    expect(result.errors?.[0]).toMatch(/dimension|pixel/i);
  });

  it('an empty buffer is handled safely', async () => {
    const result = await analyzeQrCodes(Buffer.alloc(0));
    expect(result.detected).toBe(false);
    expect(result.codes).toEqual([]);
  });

  it('never executes or evaluates decoded payload content (a QR encoding script-like text stays inert data)', async () => {
    const png = await qrPng('<script>alert(1)</script>');
    const result = await analyzeQrCodes(png);
    expect(result.codes[0].payload).toBe('<script>alert(1)</script>');
    expect(result.codes[0].type).toBe('TEXT');
  });
});
